"""Curated additions checked by the coordinating researcher, 2026-10-27."""
import json
from pathlib import Path

p=Path(__file__).resolve().parent/'research'/'agastya'/'expansion'
p.mkdir(exist_ok=True)
nodes=[
 ('buddhist','Agastya · Buddhacarita reception','agastya_facet'),
 ('root_buddhacarita','Buddhacarita','text'),
 ('root_udayin','Udāyin · Buddhacarita witness','person'),
 ('root_prince','The prince · Buddhacarita witness','person'),
 ('root_rohini','Rohiṇī · Buddhacarita witness','celestial'),
 ('root_soma','Soma · Buddhacarita witness','deity'),
 ('root_brihaddevata','Bṛhaddevatā','text'),
 ('root_student','Unnamed student · Bṛhaddevatā witness','person'),
 ('root_agni','Agni','deity'),
 ('root_brhaspati','Bṛhaspati','deity'),
 ('root_heaven_earth','Heaven and Earth · divine pair','deity_collective'),
 ('root_all_gods','All Gods · Viśvedevas','deity_collective'),
]
sources=[
 dict(id='root_bc4',title='Buddhacarita, Book IV, The Women Rejected',url='https://ancient-buddhist-texts.net/English-Texts/Buddhacarita/04-Book-IV.htm',kind='primary_translation',edition='E. B. Cowell translation; Ancient Buddhist Texts edition',locator='4.62–83, especially 4.73',accessed='2026-10-27'),
 dict(id='root_bc473',title='Buddhacarita 4.73: Sanskrit and Cowell translation',url='https://www.wisdomlib.org/buddhism/book/the-buddha-carita-sanskrit/d/doc345043.html',kind='primary_translation',edition='Cowell translation reproduced with Sanskrit; website autogenerated grammatical analysis not relied upon',locator='4.73',accessed='2026-10-27'),
 dict(id='root_bd4',title='Bṛhaddevatā 4.55–64, Agastya and Lopāmudrā',url='https://www.wisdomlib.org/hinduism/book/brihaddevata-attributed-to-shaunaka/d/doc1621782.html',kind='primary_translation_ocr',edition='A. A. Macdonell 1904 translation with apparatus; unproofread OCR, scan collation pending',locator='4.55–64; printed pp. 142–144 / scan pages 162–164',accessed='2026-10-27')
]
claims=[]
def c(facet,a,pred,b,src,loc,summary,category='relationship',status='translation_checked',speaker=None,note=''):
 claims.append(dict(id=f'REX{len(claims)+1:03}',facet=facet,subject=a,predicate=pred,object=b,source=src,locator=loc,summary=summary,category=category,status=status,speaker=speaker,note=note,original_language_reviewed=False))
c('buddhist','root_buddhacarita','explicitly_names','buddhist','root_bc473','4.73','Agastya is named in an example used in a debate about desire.','text')
c('buddhist','root_udayin','cites_as_precedent','buddhist','root_bc4','4.62–73','Udāyin names Agastya while arguing with the prince.','incoming',speaker='Udāyin',note='A character’s retrospective example; not a meeting with Agastya.')
c('buddhist','root_udayin','addresses','root_prince','root_bc4','4.62–83','The prince hears and answers Udāyin’s arguments.','relationship',speaker='Udāyin and the prince',note='This links the referring voice to its narrative audience, not the prince to Agastya personally.')
c('buddhist','buddhist','is_said_to_desire','root_rohini','root_bc473','4.73','Udāyin’s example says Agastya desired Rohiṇī.','relationship',speaker='Udāyin',note='Narrative allegation in a rhetorical example, not independent biographical confirmation.')
c('buddhist','root_rohini','is_described_as_wife_of','root_soma','root_bc473','4.73','The verse identifies Rohiṇī as Soma’s wife.','relationship',speaker='Udāyin')
c('buddhist','buddhist','story_also_names','lopamudra','root_bc473','4.73','The same verse also names Lopāmudrā.','relationship',speaker='Udāyin',note='The interpretation of the second half requires comparison of editions/translations; no new genealogical inference is imposed.')
c('vedic','root_brihaddevata','reinterprets_dialogue_of','vedic','root_bd4','4.57–60','A later explanatory narrative assigns the marital dialogue and student’s response.','text',note='OCR translation checked; original printed scan and Sanskrit not collated.')
c('vedic','lopamudra','is_assigned_speech_in','vedic','root_bd4','4.58; RV 1.179.1–2','Lopāmudrā is assigned the first two verses.','incoming','editorial_attribution',speaker='Lopāmudrā, by Bṛhaddevatā attribution')
c('vedic','vedic','is_assigned_reply_to','lopamudra','root_bd4','4.58; RV 1.179.3–4','Agastya is assigned the next two verses.','outgoing','editorial_attribution',speaker='Agastya, by Bṛhaddevatā attribution')
c('vedic','root_student','is_assigned_final_verses_about','vedic','root_bd4','4.59; RV 1.179.5–6','The unnamed student is assigned the concluding verses.','incoming','editorial_attribution',note='This student belongs to an explanatory tradition; no personal name is supplied.')
c('vedic','vedic','reassures','root_student','root_bd4','4.60','The sage and his wife reassure their student.','outgoing',speaker='Agastya and Lopāmudrā',note='Later reception of the hymn, not an extra verse of the Ṛgveda; unproofread OCR.')
for target,loc,hymn in [('asvins','4.61','1.180–184'),('root_heaven_earth','4.61–62','1.185'),('root_all_gods','4.62','1.186'),('root_agni','4.62','1.189'),('root_brhaspati','4.63','1.190')]:
 c('vedic','vedic','is_attributed_praise_of',target,'root_bd4',f'{loc}; RV {hymn}',f'The catalogue assigns this praise to Agastya.','outgoing','editorial_attribution',note='A later hymn catalogue’s attribution; original hymns require their own source-level reading. Unproofread OCR.')
notes=[
 dict(person_id='root_udayin',findings=['A newly traced referring voice in Buddhacarita 4.62–73.'],open_questions=['Compare Sanskrit editions and translations; do not automatically merge with other Udayins in Buddhist literature.']),
 dict(person_id='root_rohini',findings=['Named in Udāyin’s example concerning Agastya.'],open_questions=['Distinguish this celestial Rohiṇī from human namesakes and other narrative roles.']),
 dict(person_id='root_student',findings=['A later explanatory tradition assigns RV1.179.5–6 to an unnamed pupil.'],open_questions=['Compare the Bṛhaddevatā apparatus, Anukramaṇī and Sāyaṇa; student name remains unknown.'])
]
out=dict(nodes=[dict(id=i,label=l,type=t) for i,l,t in nodes],sources=sources,claims=claims,person_notes=notes,search_log=[dict(query='Buddhacarita 4.62–83 Agastya Rohini Udāyin',outcome='Read Cowell Book IV and checked the verse separately; no date or personal meeting inferred.'),dict(query='Bṛhaddevatā 4.55–64 Agastya Lopāmudrā',outcome='Read the OCR translation and apparatus warnings; source marked OCR, original-language and scan review pending.')])
(p/'reception.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(f'{len(claims)} coordinating-researcher additions')
